#[rustler::nif]
pub fn extraction_result_to_djot(result: Option<String>) -> Result<String, String> {
    let result_core: Option<kreuzberg::ExtractionResult> = result
        .map(|s| serde_json::from_str::<kreuzberg::ExtractionResult>(&s))
        .transpose()
        .map_err(|e| e.to_string())?;
    let result = kreuzberg::extractors::djot_format::extraction_result_to_djot(
        result_core.as_ref().unwrap_or(&Default::default()),
    )
    .map_err(|e| e.to_string())?;
    Ok(result)
}

