pub fn serialize_to_toon(result: Option<String>) -> Result<String, String> {
    let result_core: Option<kreuzberg::ExtractionResult> = result
        .map(|s| serde_json::from_str::<kreuzberg::ExtractionResult>(&s))
        .transpose()
        .map_err(|e| e.to_string())?;
    let result =
        kreuzberg::serialize_to_toon(result_core.as_ref().unwrap_or(&Default::default())).map_err(|e| e.to_string())?;
    Ok(result)
}

